        entry = _GRAPHS.get(key)
        if entry is not None:
            entry[0].replay()
            return entry[1]
        if len(_GRAPHS) < _MAX_GRAPHS:
            try:
                entry = _capture(x, y)
            except Exception:
                _GRAPHS_DISABLED = True
                _GRAPHS.clear()
            else:
                _GRAPHS[key] = entry
                return entry[1]
    return _affine(x, y)
