# half of the reference numerator:
#     lerp(x, y, 3/8) == 0.625*x + 0.375*y == 0.5*(1.25*x + 0.75*y)
# Scaling that by two and dropping the 1/8 bias reproduces the reference
# expression: 3/8, 2 and 1/8 are all exact in fp32, so the result only differs
# from the reference by ordinary rounding, far below atol/rtol = 1e-5.
_LINEAR_WEIGHT = 0.375   # 3/8
_RESCALE = 2.0           # reference bias is -2 * _BIAS_HALF
_BIAS_HALF = 0.125       # 1/8
_LERP = getattr(torch, 'lerp', None)
_BIAS_CACHE = {}

def _bias_for(x):
    key = (x.device, x.dtype)
    bias = _BIAS_CACHE.get(key)
    if bias is None:
        bias = torch.tensor(_BIAS_HALF, device=x.device, dtype=x.dtype)
        _BIAS_CACHE[key] = bias
    return bias

